import {expect,test,vi} from 'vitest';
import reference from './fixtures/npc-critical-reference.json';
import {npcFootBulletCritical} from '../src/ped/nativeNpcCritical';

// Expected bits/call counts are captures from the pinned machine code, not generated by the TS implementation.
test.each(reference.cases)('native firearm critical reference $stance/$weapon/$piece/noCritical=$noCritical',row=>{
 const victim={pedType:row.stance==='foot'?'CIVFEMALE':row.stance==='player'?'PLAYER1':'PLAYER2',noCriticalHits:row.noCritical};
 for(let sample=0;sample<8;sample++){
  const random=vi.fn(()=>sample),actual=npcFootBulletCritical(victim,row.weapon,row.piece,random);expect(actual).toBe(!!(row.forceMask&(1<<sample)));expect(random).toHaveBeenCalledTimes(row.randomCalls);
 }
});
